import { Component, OnInit } from '@angular/core';
import { CommonModule, DecimalPipe } from '@angular/common';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { PromptService } from '../../../core/services/prompt.service';
import { Prompt } from '../../../shared/models/models';

@Component({
  selector: 'app-prompt-detail',
  standalone: true,
  imports: [CommonModule, RouterLink, DecimalPipe],
  templateUrl: './prompt-detail.component.html',
})
export class PromptDetailComponent implements OnInit {
  prompt: Prompt | null = null;
  loading = true;
  error = '';

  constructor(private route: ActivatedRoute, private promptService: PromptService) {}

  ngOnInit(): void {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    this.promptService.getOne(id).subscribe({
      next: p => { this.prompt = p; this.loading = false; },
      error: () => { this.error = 'Prompt not found.'; this.loading = false; },
    });
  }

  complexityLabel(n: number): string {
    if (n <= 3) return 'low';
    if (n <= 6) return 'medium';
    return 'high';
  }

  get complexityBar(): number[] {
    return Array.from({ length: 10 }, (_, i) => i + 1);
  }

  copyContent(): void {
    if (this.prompt) {
      navigator.clipboard.writeText(this.prompt.content);
    }
  }
}
<div class="page page-narrow">
  <a routerLink="/prompts" class="back-link">← Back to Library</a>

  <div class="state-center" *ngIf="loading">
    <div class="loader"></div><p>Loading prompt…</p>
  </div>

  <div class="alert alert-error" *ngIf="error">{{ error }}</div>

  <article class="detail-card" *ngIf="prompt">
    <header class="detail-header">
      <div class="detail-meta">
        <span class="complexity-badge badge-{{ complexityLabel(prompt.complexity) }}">
          {{ complexityLabel(prompt.complexity) | titlecase }}
        </span>
        <span class="meta-date">{{ prompt.created_at | date:'longDate' }}</span>
      </div>
      <h1 class="detail-title">{{ prompt.title }}</h1>

      <!-- Tags -->
      <div class="detail-tags" *ngIf="prompt.tags.length">
        <span class="tag" *ngFor="let t of prompt.tags">{{ t.name }}</span>
      </div>
    </header>

    <!-- Complexity bar -->
    <div class="complexity-section">
      <span class="section-label">Complexity</span>
      <div class="complexity-bar">
        <div
          *ngFor="let n of complexityBar"
          class="bar-segment"
          [class.filled]="n <= prompt.complexity"
          [class.segment-low]="n <= 3"
          [class.segment-med]="n > 3 && n <= 6"
          [class.segment-high]="n > 6">
        </div>
        <span class="bar-value">{{ prompt.complexity }}/10</span>
      </div>
    </div>

    <!-- Content -->
    <div class="content-section">
      <span class="section-label">Prompt</span>
      <div class="prompt-content">{{ prompt.content }}</div>
      <button class="btn btn-ghost btn-sm copy-btn"
        (click)="copyContent()"
        #copyBtn>
        📋 Copy Prompt
      </button>
    </div>

    <!-- View counter -->
    <footer class="detail-footer">
      <div class="view-counter">
        <span class="view-icon">👁</span>
        <span class="view-count">{{ prompt.view_count | number }}</span>
        <span class="view-label">{{ prompt.view_count === 1 ? 'view' : 'views' }}</span>
        <span class="view-note">(live from Redis)</span>
      </div>
    </footer>
  </article>
</div>
